  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_01927",
          "explanation": "The doctor converted a complex discharge instruction into a simple caregiver rule.",
          "quote": "先测再吃再打"
        },
        {
          "event_id": "lite_evt_02080",
          "explanation": "The doctor adapted communication to an exhausted caregiver.",
          "quote": "你困得不行了还撑着问我这么细"
        }
      ],
      "completion": "complete",
      "explanation": "HO1 was triggered by low health literacy, caregiver fatigue, and post-stroke complexity; the doctor repeatedly used plain, supportive, non-shaming language and integrated it into practical instructions. This did not cure the RC2 error but had meaningful communication impact.",
